      url "https://github.com/richarddavenport/swarmctl-dist/releases/download/v0.20.0/swarmctl_darwin_arm64"
      sha256 "4bc5fa91bc7ea1b2987f3f91f3891804e64035d0570df1993c0c1ccfa0f121cb"
