    on_intel do
      url "https://github.com/richarddavenport/swarmctl-dist/releases/download/v0.20.0/swarmctl_darwin_amd64"
      sha256 "5262a87bda02e223b282ec1e1dae8f27c19a2b393ad6d03660924443c4cf5c4a"
    end
  end

  on_linux do
    on_arm do
